  <button id="step1">Rotate Camera 2</button>
  <button id="step2">Translate Camera 2</button>
</div>
<div id="stepNarration" style="max-width:245px;line-height:1.28;background:rgba(255,255,255,0.9);border:1px solid #d8d8d8;border-radius:6px;padding:7px 9px;">
  Here, you see the red ray from Camera 1 and its red epipolar-line projection on image plane 2.
</div>
