Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Separation r
  <input type="range" id="separation" min="1" max="4" step="0.1" value="2">
  <span id="sepVal" style="font-size:10px">2.0</span>
</label>
<button id="btnStep1">Step 1: Ground state</button>
<button id="btnStep2">Step 2: Halve distance</button>
<button id="btnStep3">Step 3: Double distance</button>
<div id="stepNarration" style="font-size:10px;color:#333;margin-top:4px;min-height:30px;"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ──────────────────────────────────────────────────────────
   guide sphere   → SphereGeometry(2,32,32) MeshBasicMaterial grey opacity 0.06
   sphere outline → LineLoop circle radius 2 in XY plane (silhouette), #999
   equator        → LineLoop circle radius 2 in XZ plane, #bbbbbb
   vert axis      → Line dashed (0,-2.6,0)-(0,2.6,0) #888
   horiz axis     → Line dashed (-2.6,0,0)-(2.6,0,0) #888
   proton         → SphereGeometry(0.18,16,16) #1a3a8f at origin
   electron       → SphereGeometry(0.12,16,16) #6fb3d8
   meridian arc   → Line from (0,2,0) to electron along meridian #5599cc
   r line         → Line origin→electron, black
   F arrow        → Group(cylinder+cone) #cc2222 electron→proton
   guide vert     → Line dashed electron→(xe,0,ze) #88bbdd
   guide horiz    → Line dashed (xe,0,ze)→(xe,0,0) #88bbdd
*/

const R_SPHERE = 2;
const K_COULOMB = 8.99e9;
const E_CHARGE = 1.6e-19;
const A0 = 5.29e-11; // Bohr radius in meters

// State
let theta = THREE.MathUtils.degToRad(45); // polar from +Y
let phi = THREE.MathUtils.degToRad(35);   // azimuthal from +Z toward +X
let sepR = 2;

function electronPos() {
  return new THREE.Vector3(
    sepR * Math.sin(theta) * Math.sin(phi),
    sepR * Math.cos(theta),
    sepR * Math.sin(theta) * Math.cos(phi)
  );
}

function forceMagnitude(rUnits) {
  const rMeters = (rUnits / 2) * A0;
  return K_COULOMB * E_CHARGE * E_CHARGE / (rMeters * rMeters);
}

function displayForceLen(rUnits) {
  return Math.min(4 / (rUnits * rUnits), 2.4);
}

// ── Guide sphere (low-opacity shell) ──
const sphereGeo = new THREE.SphereGeometry(R_SPHERE, 32, 32);
const sphereMat = new THREE.MeshBasicMaterial({ color: 0x999999, transparent: true, opacity: 0.06, side: THREE.DoubleSide });
const guideSphere = new THREE.Mesh(sphereGeo, sphereMat);
scene.add(guideSphere);

// ── Sphere silhouette (LineLoop in a plane facing camera roughly) ──
// We'll draw a great circle in the XY plane as the main silhouette
const silPts = [];
for (let i = 0; i <= 128; i++) {
  const a = (i / 128) * Math.PI * 2;
  silPts.push(new THREE.Vector3(R_SPHERE * Math.cos(a), R_SPHERE * Math.sin(a), 0));
}
const silGeo = new THREE.BufferGeometry().setFromPoints(silPts);
const silMat = new THREE.LineBasicMaterial({ color: 0x999999 });
const silhouette = new THREE.LineLoop(silGeo, silMat);
scene.add(silhouette);

// ── Equatorial ellipse (circle in XZ plane) ──
const eqPts = [];
for (let i = 0; i <= 128; i++) {
  const a = (i / 128) * Math.PI * 2;
  eqPts.push(new THREE.Vector3(R_SPHERE * Math.cos(a), 0, R_SPHERE * Math.sin(a)));
}
const eqGeo = new THREE.BufferGeometry().setFromPoints(eqPts);
const eqMat = new THREE.LineBasicMaterial({ color: 0xbbbbbb });
const equator = new THREE.LineLoop(eqGeo, eqMat);
scene.add(equator);

// ── Vertical dashed axis ──
const vAxisGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, -2.6, 0), new THREE.Vector3(0, 2.6, 0)
]);
const vAxisMat = new THREE.LineDashedMaterial({ color: 0x888888, dashSize: 0.15, gapSize: 0.1 });
const vAxis = new THREE.Line(vAxisGeo, vAxisMat);
vAxis.computeLineDistances();
scene.add(vAxis);

// ── Horizontal dashed axis ──
const hAxisGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-2.6, 0, 0), new THREE.Vector3(2.6, 0, 0)
]);
const hAxisMat = new THREE.LineDashedMaterial({ color: 0x888888, dashSize: 0.15, gapSize: 0.1 });
const hAxis = new THREE.Line(hAxisGeo, hAxisMat);
hAxis.computeLineDistances();
scene.add(hAxis);

// ── Proton ──
const protonGeo = new THREE.SphereGeometry(0.18, 16, 16);
const protonMat = new THREE.MeshBasicMaterial({ color: 0x1a3a8f });
const proton = new THREE.Mesh(protonGeo, protonMat);
scene.add(proton);

// ── Electron ──
const electronGeo = new THREE.SphereGeometry(0.12, 16, 16);
const electronMat = new THREE.MeshBasicMaterial({ color: 0x6fb3d8 });
const electron = new THREE.Mesh(electronGeo, electronMat);
scene.add(electron);
registerInteractive(electron, {
  title: 'Electron',
  tooltip: 'Drag to reposition the electron on the guide sphere',
  body: 'The electron orbits the proton. Drag it to see how the Coulomb force always points radially inward.'
});

// ── Dynamic elements (rebuilt on update) ──
let rLine, fArrowGroup, meridianArc, guideVert, guideHoriz;

function buildDashedLine(pts, color) {
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineDashedMaterial({ color, dashSize: 0.12, gapSize: 0.08 });
  const line = new THREE.Line(geo, mat);
  line.computeLineDistances();
  return line;
}

function buildArrow(from, to, color, thickness) {
  const dir = to.clone().sub(from);
  const len = dir.length();
  if (len < 0.01) return new THREE.Group();
  dir.normalize();
  const group = new THREE.Group();
  const headLen = Math.min(0.25, len * 0.3);
  const shaftLen = len - headLen;
  // Shaft
  const shaftGeo = new THREE.CylinderGeometry(thickness, thickness, shaftLen, 8);
  const shaftMat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(shaftGeo, shaftMat);
  shaft.position.y = shaftLen / 2;
  group.add(shaft);
  // Head
  const headGeo = new THREE.ConeGeometry(thickness * 2.5, headLen, 8);
  const headMat = new THREE.MeshBasicMaterial({ color });
  const head = new THREE.Mesh(headGeo, headMat);
  head.position.y = shaftLen + headLen / 2;
  group.add(head);
  // Orient group
  group.position.copy(from);
  const quat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.quaternion.copy(quat);
  return group;
}

function updateDynamic() {
  const ePos = electronPos();
  electron.position.copy(ePos);

  // Remove old dynamic objects
  if (rLine) { scene.remove(rLine); rLine.geometry.dispose(); rLine.material.dispose(); }
  if (fArrowGroup) { scene.remove(fArrowGroup); fArrowGroup.traverse(o => { o.geometry?.dispose(); o.material?.dispose(); }); }
  if (meridianArc) { scene.remove(meridianArc); meridianArc.geometry.dispose(); meridianArc.material.dispose(); }
  if (guideVert) { scene.remove(guideVert); guideVert.geometry.dispose(); guideVert.material.dispose(); }
  if (guideHoriz) { scene.remove(guideHoriz); guideHoriz.geometry.dispose(); guideHoriz.material.dispose(); }

  // r line: origin to electron
  const rGeo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), ePos]);
  const rMat = new THREE.LineBasicMaterial({ color: 0x000000 });
  rLine = new THREE.Line(rGeo, rMat);
  scene.add(rLine);

  // F arrow: from electron toward proton
  const fLen = displayForceLen(sepR);
  const dirToProton = new THREE.Vector3(0, 0, 0).sub(ePos).normalize();
  const fEnd = ePos.clone().add(dirToProton.multiplyScalar(fLen));
  fArrowGroup = buildArrow(ePos, fEnd, 0xcc2222, 0.04);
  scene.add(fArrowGroup);
  registerInteractive(fArrowGroup, {
    title: 'Coulomb Force F',
    tooltip: `|F| = ${forceMagnitude(sepR).toExponential(2)} N`,
    body: `The electrostatic force between proton and electron: |F| = ke²/r² = ${forceMagnitude(sepR).toExponential(3)} N at r = ${sepR.toFixed(1)} (in units of a₀/2).`
  });

  // Meridian arc: from top of sphere to electron along constant phi
  const arcPts = [];
  const arcSteps = 64;
  for (let i = 0; i <= arcSteps; i++) {
    const t = (i / arcSteps) * theta;
    arcPts.push(new THREE.Vector3(
      R_SPHERE * Math.sin(t) * Math.sin(phi),
      R_SPHERE * Math.cos(t),
      R_SPHERE * Math.sin(t) * Math.cos(phi)
    ));
  }
  const arcGeo = new THREE.BufferGeometry().setFromPoints(arcPts);
  const arcMat = new THREE.LineBasicMaterial({ color: 0x5599cc });
  meridianArc = new THREE.Line(arcGeo, arcMat);
  scene.add(meridianArc);

  // Projection guides
  const footPos = new THREE.Vector3(ePos.x, 0, ePos.z);
  guideVert = buildDashedLine([ePos, footPos], 0x88bbdd);
  scene.add(guideVert);

  const axisFoot = new THREE.Vector3(ePos.x, 0, 0);
  guideHoriz = buildDashedLine([footPos, axisFoot], 0x88bbdd);
  scene.add(guideHoriz);

  // Update labels
  updateLabels();
}

// ── Labels ──
let labelR, labelF, labelPlus;

function updateLabels() {
  const ePos = electronPos();
  const midR = ePos.clone().multiplyScalar(0.55);
  if (labelR) labelR.pos.copy(midR).add(new THREE.Vector3(0.15, 0.15, 0));

  const fLen = displayForceLen(sepR);
  const dirToProton = new THREE.Vector3(0, 0, 0).sub(ePos).normalize();
