Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Separation r
  <input type="range" id="separation" min="1" max="4" step="0.1" value="2">
  <span id="sepVal" style="font-size:10px">2.0</span>
</label>
<button id="btnStep1">Step 1: Ground state</button>
<button id="btnStep2">Step 2: Halve distance</button>
<button id="btnStep3">Step 3: Double distance</button>
<div id="stepNarration" style="font-size:10px;color:#333;margin-top:4px;min-height:30px;"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── Element spec ──────────────────────────────────────────────────────────
   guide sphere   → SphereGeometry(2,32,32) MeshBasicMaterial grey opacity 0.03
   silhouette     → LineLoop circle radius 2 in XY plane, #999 (main outline)
   equator        → LineLoop circle radius 2 in XZ plane, #bbbbbb
   vert axis      → Line dashed (0,-2.7,0)-(0,2.7,0) #888
   horiz axis     → Line dashed (-2.7,0,0)-(2.7,0,0) #888
   proton         → SphereGeometry(0.16,16,16) #1a3a8f at origin + white "+" label
   electron       → SphereGeometry(0.11,16,16) #6fb3d8
   meridian arc   → Line from (0,2,0) to electron along meridian #5599cc
   r line         → Line origin→electron, black thin
   F arrow        → Group(cylinder+cone) #cc2222 electron→proton
   guide vert     → Line dashed electron→(xe,0,ze) #88bbdd
   guide horiz    → Line dashed (xe,0,ze)→(xe,0,0) #88bbdd
*/

const R_SPHERE = 2;
const K_COULOMB = 8.99e9;
const E_CHARGE = 1.6e-19;
const A0 = 5.29e-11;

// State
let theta = THREE.MathUtils.degToRad(55); // polar from +Y
let phi = THREE.MathUtils.degToRad(35);   // azimuthal from +Z toward +X
let sepR = 2;

function electronPos() {
  return new THREE.Vector3(
    sepR * Math.sin(theta) * Math.sin(phi),
    sepR * Math.cos(theta),
    sepR * Math.sin(theta) * Math.cos(phi)
  );
}

function forceMagnitude(rUnits) {
  const rMeters = (rUnits / 2) * A0;
  return K_COULOMB * E_CHARGE * E_CHARGE / (rMeters * rMeters);
}

function displayForceLen(rUnits) {
  return Math.min(4 / (rUnits * rUnits), 2.4);
}

// ── Guide sphere (very low opacity) ──
const sphereGeo = new THREE.SphereGeometry(R_SPHERE, 32, 32);
const sphereMat = new THREE.MeshBasicMaterial({ color: 0xaaaaaa, transparent: true, opacity: 0.03, side: THREE.DoubleSide });
const guideSphere = new THREE.Mesh(sphereGeo, sphereMat);
scene.add(guideSphere);

// ── Sphere silhouette (circle in XY plane - the main visible outline) ──
const silPts = [];
for (let i = 0; i <= 128; i++) {
  const a = (i / 128) * Math.PI * 2;
  silPts.push(new THREE.Vector3(R_SPHERE * Math.cos(a), R_SPHERE * Math.sin(a), 0));
}
const silGeo = new THREE.BufferGeometry().setFromPoints(silPts);
const silMat = new THREE.LineBasicMaterial({ color: 0x999999 });
const silhouette = new THREE.LineLoop(silGeo, silMat);
scene.add(silhouette);

// ── Equatorial ellipse (circle in XZ plane) ──
const eqPts = [];
for (let i = 0; i <= 128; i++) {
  const a = (i / 128) * Math.PI * 2;
  eqPts.push(new THREE.Vector3(R_SPHERE * Math.cos(a), 0, R_SPHERE * Math.sin(a)));
}
const eqGeo = new THREE.BufferGeometry().setFromPoints(eqPts);
const eqMat = new THREE.LineBasicMaterial({ color: 0xbbbbbb });
const equator = new THREE.LineLoop(eqGeo, eqMat);
scene.add(equator);

// ── Vertical dashed axis ──
const vAxisGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, -2.7, 0), new THREE.Vector3(0, 2.7, 0)
]);
const vAxisMat = new THREE.LineDashedMaterial({ color: 0x888888, dashSize: 0.15, gapSize: 0.1 });
const vAxis = new THREE.Line(vAxisGeo, vAxisMat);
vAxis.computeLineDistances();
scene.add(vAxis);

// ── Horizontal dashed axis ──
const hAxisGeo = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-2.7, 0, 0), new THREE.Vector3(2.7, 0, 0)
]);
const hAxisMat = new THREE.LineDashedMaterial({ color: 0x888888, dashSize: 0.15, gapSize: 0.1 });
const hAxis = new THREE.Line(hAxisGeo, hAxisMat);
hAxis.computeLineDistances();
scene.add(hAxis);

// ── Proton ──
const protonGeo = new THREE.SphereGeometry(0.16, 16, 16);
const protonMat = new THREE.MeshBasicMaterial({ color: 0x1a3a8f });
const proton = new THREE.Mesh(protonGeo, protonMat);
scene.add(proton);

// ── Electron ──
const electronGeo = new THREE.SphereGeometry(0.11, 16, 16);
const electronMat = new THREE.MeshBasicMaterial({ color: 0x6fb3d8 });
const electron = new THREE.Mesh(electronGeo, electronMat);
scene.add(electron);
registerInteractive(electron, {
  title: 'Electron',
  tooltip: 'Drag to reposition the electron on the guide sphere',
  body: 'The electron orbits the proton. Drag it to see how the Coulomb force always points radially inward toward the proton.'
});

// ── Dynamic elements ──
let rLine, fArrowGroup, meridianArc, guideVert, guideHoriz;

function buildDashedLine(pts, color) {
  const geo = new THREE.BufferGeometry().setFromPoints(pts);
  const mat = new THREE.LineDashedMaterial({ color, dashSize: 0.1, gapSize: 0.07 });
  const line = new THREE.Line(geo, mat);
  line.computeLineDistances();
  return line;
}

function buildArrow(from, to, color, thickness) {
  const dir = to.clone().sub(from);
  const len = dir.length();
  if (len < 0.01) return new THREE.Group();
  dir.normalize();
  const group = new THREE.Group();
  const headLen = Math.min(0.22, len * 0.3);
  const shaftLen = len - headLen;
  const shaftGeo = new THREE.CylinderGeometry(thickness, thickness, shaftLen, 8);
  const shaftMat = new THREE.MeshBasicMaterial({ color });
  const shaft = new THREE.Mesh(shaftGeo, shaftMat);
  shaft.position.y = shaftLen / 2;
  group.add(shaft);
  const headGeo = new THREE.ConeGeometry(thickness * 2.8, headLen, 8);
  const headMat = new THREE.MeshBasicMaterial({ color });
  const head = new THREE.Mesh(headGeo, headMat);
  head.position.y = shaftLen + headLen / 2;
  group.add(head);
  group.position.copy(from);
  const quat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.quaternion.copy(quat);
  return group;
}

function updateDynamic() {
  const ePos = electronPos();
  electron.position.copy(ePos);

  if (rLine) { scene.remove(rLine); rLine.geometry.dispose(); rLine.material.dispose(); }
  if (fArrowGroup) { scene.remove(fArrowGroup); fArrowGroup.traverse(o => { o.geometry?.dispose(); o.material?.dispose(); }); }
  if (meridianArc) { scene.remove(meridianArc); meridianArc.geometry.dispose(); meridianArc.material.dispose(); }
  if (guideVert) { scene.remove(guideVert); guideVert.geometry.dispose(); guideVert.material.dispose(); }
  if (guideHoriz) { scene.remove(guideHoriz); guideHoriz.geometry.dispose(); guideHoriz.material.dispose(); }

  // r line: origin to electron
  const rGeo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), ePos]);
  const rMat = new THREE.LineBasicMaterial({ color: 0x000000 });
  rLine = new THREE.Line(rGeo, rMat);
  scene.add(rLine);

  // F arrow: from electron toward proton (attractive)
  const fLen = displayForceLen(sepR);
  const dirToProton = new THREE.Vector3(0, 0, 0).sub(ePos).normalize();
  const fEnd = ePos.clone().add(dirToProton.clone().multiplyScalar(fLen));
  fArrowGroup = buildArrow(ePos, fEnd, 0xcc2222, 0.035);
  scene.add(fArrowGroup);
  registerInteractive(fArrowGroup, {
    title: 'Coulomb Force F',
    tooltip: `|F| = ${forceMagnitude(sepR).toExponential(2)} N`,
    body: `The electrostatic attractive force: |F| = ke²/r² = ${forceMagnitude(sepR).toExponential(3)} N at r = ${sepR.toFixed(1)} (units of a₀/2). Direction is always radially inward.`
  });

  // Meridian arc: from top of sphere (0, R, 0) to electron along constant phi
  const arcPts = [];
  const arcSteps = 64;
  for (let i = 0; i <= arcSteps; i++) {
    const t = (i / arcSteps) * theta;
    arcPts.push(new THREE.Vector3(
      R_SPHERE * Math.sin(t) * Math.sin(phi),
      R_SPHERE * Math.cos(t),
      R_SPHERE * Math.sin(t) * Math.cos(phi)
    ));
  }
  const arcGeo = new THREE.BufferGeometry().setFromPoints(arcPts);
  const arcMat = new THREE.LineBasicMaterial({ color: 0x5599cc });
  meridianArc = new THREE.Line(arcGeo, arcMat);
  scene.add(meridianArc);

  // Projection guides: electron down to equatorial plane
  const footPos = new THREE.Vector3(ePos.x, 0, ePos.z);
  guideVert = buildDashedLine([ePos, footPos], 0x88bbdd);
  scene.add(guideVert);

  // From foot to horizontal axis (project onto X axis at z=0)
  const axisFoot = new THREE.Vector3(ePos.x, 0, 0);
  guideHoriz = buildDashedLine([footPos, axisFoot], 0x88bbdd);
  scene.add(guideHoriz);

  updateLabels();
}

// ── Labels ──
let labelR, labelF, labelPlus;

function updateLabels() {
  const ePos = electronPos();
  // r label: midpoint of r line, offset above
  const midR = ePos.clone().multiplyScalar(0.5);
  if (labelR) labelR.pos.copy(midR).add(new THREE.Vector3(0.12, 0.18, 0));

  // F label: beside the arrow, offset to the left
  const fLen = displayForceLen(sepR);
  const dirToProton = new THREE.Vector3(0, 0, 0).sub(ePos).normalize();
  const fMid = ePos.clone().add(dirToProton.clone().multiplyScalar(fLen * 0.45));
  if (labelF) labelF.pos.copy(fMid).add(new THREE.Vector3(-0.22, -0.12, 0));
}

labelPlus = addLabel('<b style="color:#fff;font-size:14px">+</b>', new THREE.Vector3(0, 0, 0), { offset: [0, 0] });
labelR = addLabel('<i style="font-size:16px">r</i>', new THREE.Vector3(0.5, 0.7, 0.4), { fontSize: '16px', bold: true, color: '#111' });
labelF = addLabel('<i style="font-size:16px">F</i>', new THREE.Vector3(0.3, 0.5, 0.3), { fontSize: '16px', bold: true, color: '#cc2222' });

// ── Camera: front-on with slight elevation, electron on right ──
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 0,
  elevationDeg: 15,
  rollDeg: 0,
  heightFraction: 0.75,
  target: [0, 0, 0]
});

// Disable orbit - drag is for electron repositioning
controls.enableRotate = false;
controls.enablePan = false;
controls.enableZoom = false;

// ── Initial build ──
updateDynamic();

// ── Slider ──
const sepSlider = document.getElementById('separation');
const sepValSpan = document.getElementById('sepVal');
sepSlider.addEventListener('input', () => {
  sepR = parseFloat(sepSlider.value);
  sepValSpan.textContent = sepR.toFixed(1);
  updateDynamic();
});

// ── Electron drag ──
const dragRaycaster = new THREE.Raycaster();
const dragPointer = new THREE.Vector2();
let isDragging = false;

canvas.addEventListener('pointerdown', (e) => {
  const rect = canvas.getBoundingClientRect();
  dragPointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPointer.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  dragRaycaster.setFromCamera(dragPointer, camera);
  const hits = dragRaycaster.intersectObject(electron);
  if (hits.length > 0) {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    e.preventDefault();
  }
});

canvas.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  const rect = canvas.getBoundingClientRect();
  dragPointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPointer.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  dragRaycaster.setFromCamera(dragPointer, camera);
  const sphereForRaycast = new THREE.Sphere(new THREE.Vector3(0, 0, 0), sepR);
  const target = new THREE.Vector3();
  const hit = dragRaycaster.ray.intersectSphere(sphereForRaycast, target);
  if (hit) {
    theta = Math.acos(Math.max(-1, Math.min(1, target.y / sepR)));
    phi = Math.atan2(target.x, target.z);
    updateDynamic();
  }
});

canvas.addEventListener('pointerup', () => {
  isDragging = false;
  canvas.style.cursor = 'default';
});

// ── Demo steps ──
const steps = [
  { title: 'Ground-state setup', narration: 'At r = 2 the electron sits on the guide sphere; the red F arrow points from the electron directly back to the proton along r, showing an attractive radial force.', separation: 2 },
  { title: 'Halve the distance', narration: 'Drag r down to 1: the electron moves inward and the F arrow grows to about four times its length — the inverse-square strengthening made visible.', separation: 1 },
  { title: 'Double the distance', narration: 'Push r out to 4: the electron moves beyond the guide sphere and the F arrow shrinks to about a quarter, confirming |F| ∝ 1/r² while the direction stays radial.', separation: 4 }
];

const narrationDiv = document.getElementById('stepNarration');
let tweenId = null;

function goToStep(idx) {
  const step = steps[idx];
  narrationDiv.textContent = step.narration;
  const startVal = sepR;
  const endVal = step.separation;
  const duration = 800;
  const startTime = performance.now();
  if (tweenId) cancelAnimationFrame(tweenId);
  function tween() {
    const elapsed = performance.now() - startTime;
    const t = Math.min(elapsed / duration, 1);
    const eased = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    sepR = startVal + (endVal - startVal) * eased;
    sepSlider.value = sepR;
    sepValSpan.textContent = sepR.toFixed(1);
    updateDynamic();
    if (t < 1) tweenId = requestAnimationFrame(tween);
  }
  tweenId = requestAnimationFrame(tween);
}

document.getElementById('btnStep1').addEventListener('click', () => goToStep(0));
document.getElementById('btnStep2').addEventListener('click', () => goToStep(1));
document.getElementById('btnStep3').addEventListener('click', () => goToStep(2));

window.goToStep = goToStep;
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

