   silhouette     → LineLoop circle radius 2 in XY plane, #999 (main outline)
   equator        → LineLoop circle radius 2 in XZ plane, #bbbbbb
   vert axis      → Line dashed (0,-2.7,0)-(0,2.7,0) #888
   horiz axis     → Line dashed (0,0,0)-(2.7,0,0) #888  (RIGHT side only)
   depth axis     → Line dashed (0,0,0)-(-1.8,0,1.8) #888 (lower-left, into page)
   proton         → SphereGeometry(0.16,16,16) #1a3a8f at origin + white "+" label
   electron       → SphereGeometry(0.11,16,16) #6fb3d8  (upper-RIGHT)
   meridian arc   → Line from (0,2,0) to electron along meridian #5599cc
   r line         → Line origin→electron, black thin
   F arrow        → Group(cylinder+cone) #cc2222 electron→proton
   guide vert     → Line dashed electron→(xe,0,ze) #88bbdd
   guide horiz    → Line dashed (xe,0,ze)→(xe,0,0) #88bbdd
*/

const R_SPHERE = 2;
const K_COULOMB = 8.99e9;
const E_CHARGE = 1.6e-19;
const A0 = 5.29e-11;

// State — electron in upper-RIGHT quadrant (positive x)
let theta = THREE.MathUtils.degToRad(55); // polar from +Y
let phi = THREE.MathUtils.degToRad(35);   // azimuthal from +Z toward +X
let sepR = 2;

function electronPos() {
  return new THREE.Vector3(
    sepR * Math.sin(theta) * Math.sin(phi),
    sepR * Math.cos(theta),
    sepR * Math.sin(theta) * Math.cos(phi)
  );
}

function forceMagnitude(rUnits) {
  const rMeters = (rUnits / 2) * A0;
  return K_COULOMB * E_CHARGE * E_CHARGE / (rMeters * rMeters);
}

function displayForceLen(rUnits) {
  return Math.min(4 / (rUnits * rUnits), 2.4);
}

// ── Guide sphere (very low opacity) ──
const guideSphere = new THREE.Mesh(
  new THREE.SphereGeometry(R_SPHERE, 32, 32),
  new THREE.MeshBasicMaterial({ color: 0xaaaaaa, transparent: true, opacity: 0.03, side: THREE.DoubleSide })
);
scene.add(guideSphere);

// ── Sphere silhouette (circle in XY plane) ──
const silPts = [];
for (let i = 0; i <= 128; i++) {
  const a = (i / 128) * Math.PI * 2;
  silPts.push(new THREE.Vector3(R_SPHERE * Math.cos(a), R_SPHERE * Math.sin(a), 0));
}
const silhouette = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints(silPts),
  new THREE.LineBasicMaterial({ color: 0x999999 })
);
scene.add(silhouette);

// ── Equatorial ellipse (circle in XZ plane) ──
const eqPts = [];
for (let i = 0; i <= 128; i++) {
  const a = (i / 128) * Math.PI * 2;
  eqPts.push(new THREE.Vector3(R_SPHERE * Math.cos(a), 0, R_SPHERE * Math.sin(a)));
}
const equator = new THREE.LineLoop(
  new THREE.BufferGeometry().setFromPoints(eqPts),
  new THREE.LineBasicMaterial({ color: 0xbbbbbb })
);
scene.add(equator);

// ── Vertical dashed axis ──
const vAxis = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, -2.7, 0), new THREE.Vector3(0, 2.7, 0)]),
  new THREE.LineDashedMaterial({ color: 0x888888, dashSize: 0.15, gapSize: 0.1 })
);
vAxis.computeLineDistances();
scene.add(vAxis);

// ── Horizontal dashed axis: RIGHT side only ──
const hAxis = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), new THREE.Vector3(2.7, 0, 0)]),
  new THREE.LineDashedMaterial({ color: 0x888888, dashSize: 0.15, gapSize: 0.1 })
);
hAxis.computeLineDistances();
scene.add(hAxis);

// ── Depth dashed axis: short, toward lower-left (into the page) ──
const dAxis = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), new THREE.Vector3(-1.8, 0, 1.8)]),
  new THREE.LineDashedMaterial({ color: 0x888888, dashSize: 0.15, gapSize: 0.1 })
);
dAxis.computeLineDistances();
scene.add(dAxis);

// ── Proton ──
const proton = new THREE.Mesh(
  new THREE.SphereGeometry(0.16, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x1a3a8f })
);
scene.add(proton);

// ── Electron ──
const electron = new THREE.Mesh(
  new THREE.SphereGeometry(0.11, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x6fb3d8 })
);
scene.add(electron);
registerInteractive(electron, {
  title: 'Electron',
  tooltip: 'Drag to reposition the electron on the guide sphere',
  body: 'The electron orbits the proton. Drag it to see how the Coulomb force always points radially inward toward the proton.'
});

// ── Dynamic element holders ──
let rLine, fArrowGroup, meridianArc, guideVert, guideHoriz;

function buildDashedLine(pts, color) {
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineDashedMaterial({ color, dashSize: 0.1, gapSize: 0.07 })
  );
  line.computeLineDistances();
  return line;
}

function buildArrow(from, to, color, thickness) {
  const dir = to.clone().sub(from);
  const len = dir.length();
  if (len < 0.01) return new THREE.Group();
  dir.normalize();
  const group = new THREE.Group();
  const headLen = Math.min(0.22, len * 0.3);
  const shaftLen = len - headLen;
  const shaft = new THREE.Mesh(
    new THREE.CylinderGeometry(thickness, thickness, shaftLen, 8),
    new THREE.MeshBasicMaterial({ color })
  );
  shaft.position.y = shaftLen / 2;
  group.add(shaft);
  const head = new THREE.Mesh(
    new THREE.ConeGeometry(thickness * 2.8, headLen, 8),
    new THREE.MeshBasicMaterial({ color })
  );
  head.position.y = shaftLen + headLen / 2;
  group.add(head);
  group.position.copy(from);
  group.quaternion.copy(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir));
  return group;
}

function disposeDyn(o) {
  if (!o) return;
  o.traverse?.(c => { c.geometry?.dispose?.(); if (c.material) c.material.dispose?.(); });
  if (o.geometry) o.geometry.dispose?.();
  if (o.material) o.material.dispose?.();
  scene.remove(o);
}

function updateDynamic() {
  const ePos = electronPos();
  electron.position.copy(ePos);

  disposeDyn(rLine); disposeDyn(fArrowGroup); disposeDyn(meridianArc);
  disposeDyn(guideVert); disposeDyn(guideHoriz);

  // r line: origin → electron
  rLine = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), ePos]),
    new THREE.LineBasicMaterial({ color: 0x000000 })
  );
  scene.add(rLine);

  // F arrow: electron → proton (attractive, radially inward)
  const fLen = displayForceLen(sepR);
  const dirToProton = new THREE.Vector3(0, 0, 0).sub(ePos).normalize();
  const fEnd = ePos.clone().add(dirToProton.clone().multiplyScalar(fLen));
  fArrowGroup = buildArrow(ePos, fEnd, 0xcc2222, 0.035);
  scene.add(fArrowGroup);
  registerInteractive(fArrowGroup, {
    title: 'Coulomb Force F',
    tooltip: `|F| = ${forceMagnitude(sepR).toExponential(2)} N`,
    body: `The electrostatic attractive force: |F| = ke²/r² = ${forceMagnitude(sepR).toExponential(3)} N at r = ${sepR.toFixed(1)} (units of a₀/2). Direction is always radially inward.`
  });

  // Meridian arc: top of sphere → electron at constant phi
  const arcPts = [];
  const arcSteps = 64;
  for (let i = 0; i <= arcSteps; i++) {
    const t = (i / arcSteps) * theta;
    arcPts.push(new THREE.Vector3(
      R_SPHERE * Math.sin(t) * Math.sin(phi),
      R_SPHERE * Math.cos(t),
      R_SPHERE * Math.sin(t) * Math.cos(phi)
    ));
  }
  meridianArc = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(arcPts),
    new THREE.LineBasicMaterial({ color: 0x5599cc })
  );
  scene.add(meridianArc);

  // Projection guides: electron → equatorial foot → horizontal axis
  const footPos = new THREE.Vector3(ePos.x, 0, ePos.z);
  guideVert = buildDashedLine([ePos, footPos], 0x88bbdd);
  scene.add(guideVert);
  const axisFoot = new THREE.Vector3(ePos.x, 0, 0);
  guideHoriz = buildDashedLine([footPos, axisFoot], 0x88bbdd);
  scene.add(guideHoriz);

  updateLabels();
}

// ── Labels ──
const labelPlus = addLabel('<b style="color:#fff;font-size:14px">+</b>', new THREE.Vector3(0, 0, 0));
const labelR = addLabel('<i>r</i>', new THREE.Vector3(0.5, 0.7, 0.4), { fontSize: '16px', bold: true, color: '#111' });
const labelF = addLabel('<i>F</i>', new THREE.Vector3(0.3, 0.5, 0.3), { fontSize: '16px', bold: true, color: '#cc2222' });

function updateLabels() {
  const ePos = electronPos();
  const midR = ePos.clone().multiplyScalar(0.55);
  labelR.pos.copy(midR).add(new THREE.Vector3(0.05, 0.22, 0));

  const fLen = displayForceLen(sepR);
  const dirToProton = new THREE.Vector3(0, 0, 0).sub(ePos).normalize();
  const fMid = ePos.clone().add(dirToProton.clone().multiplyScalar(fLen * 0.5));
  labelF.pos.copy(fMid).add(new THREE.Vector3(0.0, -0.22, 0));
}

// ── Camera: front-on to the XY plane, mirrored so +X (electron) is on the RIGHT ──
setCameraView({
  projection: 'orthographic',
  azimuthDeg: 180,
  elevationDeg: 15,
  rollDeg: 0,
  heightFraction: 0.78,
  target: [0, 0, 0]
});

// Drag is reserved for repositioning the electron
controls.enableRotate = false;
controls.enablePan = false;
controls.enableZoom = false;

updateDynamic();

// ── Slider ──
const sepSlider = document.getElementById('separation');
const sepValSpan = document.getElementById('sepVal');
sepSlider.addEventListener('input', () => {
  sepR = parseFloat(sepSlider.value);
  sepValSpan.textContent = sepR.toFixed(1);
  updateDynamic();
});

// ── Electron drag on the guide sphere ──
const dragRaycaster = new THREE.Raycaster();
const dragPointer = new THREE.Vector2();
let isDragging = false;

canvas.addEventListener('pointerdown', (e) => {
  const rect = canvas.getBoundingClientRect();
  dragPointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPointer.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  dragRaycaster.setFromCamera(dragPointer, camera);
  if (dragRaycaster.intersectObject(electron).length > 0) {
    isDragging = true;
    canvas.style.cursor = 'grabbing';
    e.preventDefault();
  }
});

canvas.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  const rect = canvas.getBoundingClientRect();
  dragPointer.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPointer.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  dragRaycaster.setFromCamera(dragPointer, camera);
  const target = new THREE.Vector3();
  if (dragRaycaster.ray.intersectSphere(new THREE.Sphere(new THREE.Vector3(0, 0, 0), sepR), target)) {
    theta = Math.acos(Math.max(-1, Math.min(1, target.y / sepR)));
    phi = Math.atan2(target.x, target.z);
    updateDynamic();
  }
});

canvas.addEventListener('pointerup', () => {
  isDragging = false;
  canvas.style.cursor = 'default';
});

// ── Demo steps ──
const steps = [
  { narration: 'At r = 2 the electron sits on the guide sphere (upper right); the red F arrow points from the electron directly back to the proton along r, showing an attractive radial force.', separation: 2 },
  { narration: 'Drag r down to 1: the electron moves inward and the F arrow grows to about four times its length — the inverse-square strengthening made visible.', separation: 1 },
  { narration: 'Push r out to 4: the electron moves beyond the guide sphere and the F arrow shrinks to about a quarter, confirming |F| ∝ 1/r² while the direction stays radial.', separation: 4 }
];

const narrationDiv = document.getElementById('stepNarration');
let tweenId = null;

function goToStep(idx) {
  const step = steps[idx];
  narrationDiv.textContent = step.narration;
  const startVal = sepR, endVal = step.separation, duration = 800, startTime = performance.now();
  if (tweenId) cancelAnimationFrame(tweenId);
  function tween() {
    const t = Math.min((performance.now() - startTime) / duration, 1);
    const eased = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    sepR = startVal + (endVal - startVal) * eased;
    sepSlider.value = sepR;
    sepValSpan.textContent = sepR.toFixed(1);
    updateDynamic();
    if (t < 1) tweenId = requestAnimationFrame(tween);
  }
  tweenId = requestAnimationFrame(tween);
}

document.getElementById('btnStep1').addEventListener('click', () => goToStep(0));
document.getElementById('btnStep2').addEventListener('click', () => goToStep(1));
document.getElementById('btnStep3').addEventListener('click', () => goToStep(2));
window.goToStep = goToStep;
// @FIGURE_CODE_END

